records.source:
+> math
@pointer := pointer://pointer/frame{:read(pulse), :read(position)}
@particles := compute://particles/kernel{:write(input/force-point), :write(turn)}
@particles/input/force-point <- @pointer/position
@particles/turn <- @pointer/pulse

particle-field @compute
-------------------------------------------------------------------------------
force-point := [0f32; 0f32]
row := math/mod(1f32..=3f32, 4f32)
~matrix := [row; row + 3f32]
matrix = matrix + force-point
matrix'

records.configuration:
config := {
  runtime: {
    resident-durability: "volatile"

    limits: {
      max-turn-duration-ms: 10000
    }
  }

  hosts: [
    {
      name: "pointer"
      provider: "pointer"
      settings: {}
    }

    {
      name: "particles"
      provider: "compute"
      settings: {
        region: "particle-field"
        backend: "auto"
      }
    }
  ]

  run: {
    paths: ["particles.mec"]

    grants: [
      {
        target: "pointer/frame"
        operations: ["read"]
        paths: ["pulse", "position", "pressed", "delta-seconds"]
      }

      {
        target: "particles/kernel"
        operations: ["write"]
        paths: ["input/force-point", "turn"]
      }
    ]
  }

  serve: {
    paths: ["index.html", "particles.css", "particles.mec"]
    shim: "index.html"
    wasm: "../../src/wasm/pkg"
  }
}

manifest.wgsl:
// Generic fixed-shape Mech batch kernel.
@group(0) @binding(0) var<storage, read> input_0: array<f32>;
@group(0) @binding(1) var<storage, read> state_read_1: array<f32>;
@group(0) @binding(2) var<storage, read_write> state_write_1: array<f32>;
@group(0) @binding(3) var<storage, read_write> state_write_10: array<f32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let index = gid.x;
  if (index >= 1u) { return; }
  let r0 = input_0[index * 2u + 0u];
  let r1 = input_0[index * 2u + 1u];
  let r2 = state_read_1[index * 6u + 0u];
  let r3 = state_read_1[index * 6u + 1u];
  let r4 = state_read_1[index * 6u + 2u];
  let r5 = state_read_1[index * 6u + 3u];
  let r6 = state_read_1[index * 6u + 4u];
  let r7 = state_read_1[index * 6u + 5u];
  let r8 = r2;
  let r9 = r3;
  let r10 = r4;
  let r11 = r5;
  let r12 = r6;
  let r13 = r7;
  let r14 = r8 + r0;
  let r15 = r9 + r1;
  let r16 = r10 + r0;
  let r17 = r11 + r1;
  let r18 = r12 + r0;
  let r19 = r13 + r1;
  let r20 = r14;
  let r21 = r16;
  let r22 = r18;
  let r23 = r15;
  let r24 = r17;
  let r25 = r19;
  state_write_1[index * 6u + 0u] = r14;
  state_write_1[index * 6u + 1u] = r15;
  state_write_1[index * 6u + 2u] = r16;
  state_write_1[index * 6u + 3u] = r17;
  state_write_1[index * 6u + 4u] = r18;
  state_write_1[index * 6u + 5u] = r19;
  state_write_10[index * 6u + 0u] = r20;
  state_write_10[index * 6u + 1u] = r21;
  state_write_10[index * 6u + 2u] = r22;
  state_write_10[index * 6u + 3u] = r23;
  state_write_10[index * 6u + 4u] = r24;
  state_write_10[index * 6u + 5u] = r25;
}

