records.source:
+> math
@pointer := pointer://pointer/frame{:read(pulse), :read(position)}
@particles := compute://particles/kernel{:write(input/force-point), :write(turn)}
@particles/input/force-point <- @pointer/position
@particles/turn <- @pointer/pulse

particle-field @compute
-------------------------------------------------------------------------------
force-point := [0f32; 0f32]
row := math/mod(1f32..=1024f32, 4f32)
~matrix := [row; row + 3f32]
matrix = matrix + force-point
matrix'

records.configuration:
config := {
  runtime: {
    resident-durability: "volatile"

    limits: {
      max-turn-duration-ms: 10000
    }
  }

  hosts: [
    {
      name: "pointer"
      provider: "pointer"
      settings: {}
    }

    {
      name: "particles"
      provider: "compute"
      settings: {
        region: "particle-field"
        backend: "auto"
      }
    }
  ]

  run: {
    paths: ["particles.mec"]

    grants: [
      {
        target: "pointer/frame"
        operations: ["read"]
        paths: ["pulse", "position", "pressed", "delta-seconds"]
      }

      {
        target: "particles/kernel"
        operations: ["write"]
        paths: ["input/force-point", "turn"]
      }
    ]
  }

  serve: {
    paths: ["index.html", "particles.css", "particles.mec"]
    shim: "index.html"
    wasm: "../../src/wasm/pkg"
  }
}

